<script setup>
import { ref, onMounted, onBeforeUnmount } from 'vue'
import { useMarkdownEditor, MarkdownEditorView } from '@gravity-ui/markdown-editor'
</script>

<template>
  <div class="w-full h-full flex gap-2">
    <MarkdownEditorView
      stickyToolbar
      autofocus
      :editor="editor"
      class="w-full"
    />
  </div>
</template>

<script>
export default {
  props: {
    modelValue: String, // Prop to expose the editor content
  },
  data() {
    return {
      editor: null, // Reactive data for editor instance
    }
  },
  watch: {
    modelValue(newValue) {
      if (this.editor && newValue !== this.editor.getValue()) {
        this.editor.setValue(newValue)
      }
    },
  },
  methods: {
    submitHandler() {
      const value = this.editor.getValue()
      this.$emit('update:modelValue', value) // Emit update for modelValue
    },
  },
  mounted() {
    this.editor = useMarkdownEditor({ allowHTML: false })
    this.editor.on('submit', this.submitHandler)
  },
  beforeUnmount() {
    if (this.editor) {
      this.editor.off('submit', this.submitHandler)
    }
  },
}
</script>
